       <h1>Notification settings</h1>
       <p class="helper">Choose how you want to receive product updates and alerts.</p>

       <form id="notification-form" novalidate>
         <div class="form-field">
           <fieldset>
             <legend>How do you prefer to receive notifications?</legend>
             <div class="options">
               <label class="option">
                 <input type="radio" name="notification" value="Email" />
                 <span>Email</span>
               </label>
               <label class="option">
